    BorrowRecord borrowRecord = MunicipalLibraryFactory.eINSTANCE.createBorrowRecord();
    borrowRecord.setBook(book);
    borrowRecord.setBorrowingDate(today);

    java.util.Calendar calendar = java.util.Calendar.getInstance();
    calendar.setTime(today);
    calendar.add(java.util.Calendar.DAY_OF_MONTH, 7);
    borrowRecord.setReturnDue(calendar.getTime());

    getBorrowRecords().add(borrowRecord);
    return true;
    
